export function t(key, vars){
  let s = (S[LANG] && S[LANG][key]) ?? S.de[key] ?? key;
  if(vars) s = s.replace(/\{(\w+)\}/g, (m, k) => vars[k] ?? m);
  return s;
}
// Name(n) aus dem Link: ?name=, sonst ?namen=
export const NAME = (() => { const p = new URLSearchParams(location.search); return p.get('name') || p.get('namen') || ''; })();
